inline flight::host_sdl::WgpuBlendState wgpu_particle_blend_state(flight::types::ParticleBlendMode mode) {
  {
    auto switch_value = mode;
    if (switch_value == flight::String("add")) {
      return flight::render_wgpu::get_wgpu_blend_state(std::optional<flight::String>{flight::types::blend_mode->add});
    }
    else if (switch_value == flight::String("multiply")) {
      return flight::render_wgpu::get_wgpu_blend_state(std::optional<flight::String>{flight::types::blend_mode->multiply});
    }
    else if (switch_value == flight::String("screen")) {
      return flight::render_wgpu::get_wgpu_blend_state(std::optional<flight::String>{flight::types::blend_mode->screen});
    }
    else {
      return flight::render_wgpu::get_wgpu_blend_state(std::optional<flight::String>{flight::types::blend_mode->normal});
    }
  }
  throw std::logic_error("Flight function completed without a value");
}


